card_mod.style:
/* skin-popup */
{% set skin = states('input_select.card_skin') %}
ha-card {
  background: {% if skin == 'Glass' %}rgba(255,255,255,0.02){% elif skin == 'Poster' %}radial-gradient(120% 100% at 50% 0%, rgba(255,255,255,0.065), rgba(255,255,255,0.008) 65%){% elif skin == 'Ember' %}radial-gradient(circle at top right, rgba(224,175,104,0.10), transparent 60%), linear-gradient(180deg, rgb(23,17,10) 0%, rgb(12,8,5) 100%){% elif skin == 'Violet' %}radial-gradient(circle at top right, rgba(187,154,247,0.10), transparent 60%), linear-gradient(180deg, rgb(16,13,25) 0%, rgb(7,5,12) 100%){% elif skin == 'Aurora' %}radial-gradient(circle at 12% -10%, rgba(0,188,212,0.14), transparent 45%), radial-gradient(circle at 88% -10%, rgba(187,154,247,0.13), transparent 45%), linear-gradient(180deg, rgb(9,12,19) 0%, rgb(4,5,10) 100%){% elif skin == 'Sunset' %}radial-gradient(circle at 12% -10%, rgba(224,175,104,0.14), transparent 45%), radial-gradient(circle at 88% -10%, rgba(247,118,142,0.13), transparent 45%), linear-gradient(180deg, rgb(19,13,11) 0%, rgb(9,6,5) 100%){% elif skin == 'Lagoon' %}radial-gradient(circle at 12% -10%, rgba(115,218,202,0.14), transparent 45%), radial-gradient(circle at 88% -10%, rgba(122,162,247,0.13), transparent 45%), linear-gradient(180deg, rgb(7,15,17) 0%, rgb(3,7,9) 100%){% elif skin == 'Citrus' %}radial-gradient(circle at 12% -10%, rgba(240,203,104,0.14), transparent 45%), radial-gradient(circle at 88% -10%, rgba(158,206,106,0.13), transparent 45%), linear-gradient(180deg, rgb(15,16,9) 0%, rgb(7,8,4) 100%){% elif skin == 'Watermelon' %}radial-gradient(circle at 12% -10%, rgba(244,124,178,0.14), transparent 45%), radial-gradient(circle at 88% -10%, rgba(158,206,106,0.13), transparent 45%), linear-gradient(180deg, rgb(15,12,14) 0%, rgb(6,5,6) 100%){% elif skin == 'Orchid' %}radial-gradient(circle at 12% -10%, rgba(247,118,142,0.14), transparent 45%), radial-gradient(circle at 88% -10%, rgba(187,154,247,0.13), transparent 45%), linear-gradient(180deg, rgb(17,11,19) 0%, rgb(8,5,10) 100%){% elif skin == 'Reef' %}radial-gradient(circle at 12% -10%, rgba(255,158,100,0.14), transparent 45%), radial-gradient(circle at 88% -10%, rgba(115,218,202,0.13), transparent 45%), linear-gradient(180deg, rgb(13,14,14) 0%, rgb(5,7,7) 100%){% elif skin == 'Frost' %}radial-gradient(circle at 12% -10%, rgba(125,207,255,0.12), transparent 45%), radial-gradient(circle at 88% -10%, rgba(192,202,245,0.11), transparent 45%), linear-gradient(180deg, rgb(10,13,18) 0%, rgb(4,6,9) 100%){% elif skin == 'Horizon' %}radial-gradient(130% 80% at 50% 118%, rgba(122,162,247,0.16), transparent 60%), linear-gradient(180deg, rgb(5,7,11) 0%, rgb(9,12,18) 100%){% elif skin == 'Neon Pink' %}linear-gradient(180deg, rgba(247,118,142,0.04) 0%, rgba(0,0,0,0.25) 100%){% elif skin == 'Neon Green' %}linear-gradient(180deg, rgba(158,206,106,0.04) 0%, rgba(0,0,0,0.25) 100%){% elif skin == 'Etched' %}linear-gradient(180deg, rgb(6,7,9) 0%, rgb(10,12,14) 100%){% elif skin == 'Obsidian' %}linear-gradient(180deg, rgb(2,2,3) 0%, rgb(0,0,0) 100%){% elif skin == 'Nebula' %}radial-gradient(130% 110% at 100% 100%, rgba(150,140,235,0.16), transparent 55%), linear-gradient(160deg, rgb(6,4,36) 0%, rgb(14,12,44) 40%, rgb(24,23,56) 100%){% else %}radial-gradient(circle at top right, rgba(0,188,212,0.08), transparent 60%), linear-gradient(180deg, rgb(7,15,20) 0%, rgb(3,8,11) 100%){% endif %} !important;
  backdrop-filter: {% if skin == 'Glass' %}blur(20px){% elif skin == 'Poster' %}blur(24px) saturate(1.3){% elif skin == 'Ember' %}none{% elif skin == 'Violet' %}none{% elif skin == 'Aurora' %}none{% elif skin == 'Sunset' %}none{% elif skin == 'Lagoon' %}none{% elif skin == 'Citrus' %}none{% elif skin == 'Watermelon' %}none{% elif skin == 'Orchid' %}none{% elif skin == 'Reef' %}none{% elif skin == 'Frost' %}none{% elif skin == 'Horizon' %}none{% elif skin == 'Neon Pink' %}blur(6px){% elif skin == 'Neon Green' %}blur(6px){% elif skin == 'Etched' %}none{% elif skin == 'Obsidian' %}none{% elif skin == 'Nebula' %}none{% else %}none{% endif %} !important;
  border: 1px solid {% if skin == 'Glass' %}rgba(255,255,255,0.04){% elif skin == 'Poster' %}rgba(255,255,255,0.06){% elif skin == 'Ember' %}rgba(224,175,104,0.20){% elif skin == 'Violet' %}rgba(187,154,247,0.20){% elif skin == 'Aurora' %}rgba(140,170,240,0.20){% elif skin == 'Sunset' %}rgba(236,146,123,0.20){% elif skin == 'Lagoon' %}rgba(118,190,224,0.20){% elif skin == 'Citrus' %}rgba(199,205,105,0.20){% elif skin == 'Watermelon' %}rgba(201,165,142,0.20){% elif skin == 'Orchid' %}rgba(217,136,194,0.20){% elif skin == 'Reef' %}rgba(185,188,151,0.20){% elif skin == 'Frost' %}rgba(158,204,250,0.18){% elif skin == 'Horizon' %}rgba(122,162,247,0.16){% elif skin == 'Neon Pink' %}rgba(247,118,142,0.55){% elif skin == 'Neon Green' %}rgba(158,206,106,0.55){% elif skin == 'Etched' %}rgba(255,255,255,0.05){% elif skin == 'Obsidian' %}transparent{% elif skin == 'Nebula' %}rgba(160,155,215,0.60){% else %}rgba(0,188,212,0.18){% endif %} !important;
  border-radius: 22px;
  overflow: hidden;
  position: relative;
  box-shadow: {% if skin == 'Glass' %}none{% elif skin == 'Poster' %}0 8px 24px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.07), inset 0 -1px 0 rgba(0,0,0,0.15){% elif skin == 'Ember' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.05){% elif skin == 'Violet' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.05){% elif skin == 'Aurora' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Sunset' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Lagoon' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Citrus' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Watermelon' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Orchid' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Reef' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Frost' %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06){% elif skin == 'Horizon' %}0 8px 30px rgba(0,0,0,0.55), inset 0 -1px 0 rgba(122,162,247,0.16){% elif skin == 'Neon Pink' %}0 0 16px rgba(247,118,142,0.22), inset 0 0 18px rgba(247,118,142,0.07){% elif skin == 'Neon Green' %}0 0 16px rgba(158,206,106,0.22), inset 0 0 18px rgba(158,206,106,0.07){% elif skin == 'Etched' %}inset 0 3px 10px rgba(0,0,0,0.65), inset 0 -1px 0 rgba(255,255,255,0.05){% elif skin == 'Obsidian' %}0 12px 36px rgba(0,0,0,0.75), 0 2px 6px rgba(0,0,0,0.6){% elif skin == 'Nebula' %}0 8px 24px rgba(0,0,0,0.25){% else %}0 8px 32px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.05){% endif %} !important;
}
ha-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 1px;
  background: {% if skin == 'Glass' %}none{% elif skin == 'Poster' %}linear-gradient(90deg, transparent, rgba(255,255,255,0.28), transparent){% elif skin == 'Ember' %}linear-gradient(90deg, transparent, rgba(224,175,104,0.85), transparent){% elif skin == 'Violet' %}linear-gradient(90deg, transparent, rgba(187,154,247,0.85), transparent){% elif skin == 'Aurora' %}linear-gradient(90deg, transparent, rgba(0,188,212,0.85) 35%, rgba(187,154,247,0.85) 65%, transparent){% elif skin == 'Sunset' %}linear-gradient(90deg, transparent, rgba(224,175,104,0.85) 35%, rgba(247,118,142,0.85) 65%, transparent){% elif skin == 'Lagoon' %}linear-gradient(90deg, transparent, rgba(115,218,202,0.85) 35%, rgba(122,162,247,0.85) 65%, transparent){% elif skin == 'Citrus' %}linear-gradient(90deg, transparent, rgba(240,203,104,0.85) 35%, rgba(158,206,106,0.85) 65%, transparent){% elif skin == 'Watermelon' %}linear-gradient(90deg, transparent, rgba(244,124,178,0.85) 35%, rgba(158,206,106,0.85) 65%, transparent){% elif skin == 'Orchid' %}linear-gradient(90deg, transparent, rgba(247,118,142,0.85) 35%, rgba(187,154,247,0.85) 65%, transparent){% elif skin == 'Reef' %}linear-gradient(90deg, transparent, rgba(255,158,100,0.85) 35%, rgba(115,218,202,0.85) 65%, transparent){% elif skin == 'Frost' %}linear-gradient(90deg, transparent, rgba(125,207,255,0.80) 35%, rgba(192,202,245,0.80) 65%, transparent){% elif skin == 'Horizon' %}linear-gradient(90deg, transparent, rgba(122,162,247,0.35), transparent){% elif skin == 'Neon Pink' %}linear-gradient(90deg, transparent, rgba(247,118,142,0.95), transparent){% elif skin == 'Neon Green' %}linear-gradient(90deg, transparent, rgba(158,206,106,0.95), transparent){% elif skin == 'Etched' %}linear-gradient(90deg, transparent, rgba(255,255,255,0.10), transparent){% elif skin == 'Obsidian' %}none{% elif skin == 'Nebula' %}none{% else %}linear-gradient(90deg, transparent, rgba(0,188,212,0.8), transparent){% endif %};
}
@keyframes pd-pulse { 0%,100%{opacity:1} 50%{opacity:0.35} }
.pd-led {
  display:inline-block;width:8px;height:8px;border-radius:50%;
  background:#00bcd4;
  box-shadow:0 0 10px #00bcd4, 0 0 4px #00bcd4;
  animation: pd-pulse 2s infinite;
}
/* /skin-popup */

ha-card {
  border-radius: 14px !important; --ha-card-border-radius: 14px !important; overflow: hidden !important;
}
/* skin-period */
