  box-shadow: {% if on %}{% if skin == 'Glass' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Poster' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Ember' %}0 0 16px rgba(224,175,104,0.25){% elif skin == 'Violet' %}0 0 16px rgba(187,154,247,0.25){% elif skin == 'Aurora' %}0 0 16px rgba(150,165,240,0.25){% elif skin == 'Sunset' %}0 0 16px rgba(236,146,123,0.25){% elif skin == 'Lagoon' %}0 0 16px rgba(118,190,224,0.25){% elif skin == 'Citrus' %}0 0 16px rgba(199,205,105,0.25){% elif skin == 'Watermelon' %}0 0 16px rgba(201,165,142,0.25){% elif skin == 'Orchid' %}0 0 16px rgba(217,136,194,0.25){% elif skin == 'Reef' %}0 0 16px rgba(185,188,151,0.25){% elif skin == 'Frost' %}0 0 16px rgba(158,204,250,0.25){% elif skin == 'Horizon' %}0 0 16px rgba(122,162,247,0.25){% elif skin == 'Neon Pink' %}0 0 16px rgba(247,118,142,0.25){% elif skin == 'Neon Green' %}0 0 16px rgba(158,206,106,0.25){% elif skin == 'Etched' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Obsidian' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Nebula' %}0 0 16px rgba(124,112,226,0.25){% else %}0 0 16px rgba(0,188,212,0.25){% endif %}{% else %}none{% endif %} !important;
}
