  border: 1px solid {% if on %}{% if skin == 'Glass' %}rgba(255,255,255,0.45){% elif skin == 'Poster' %}rgba(255,255,255,0.45){% elif skin == 'Ember' %}rgba(224,175,104,0.65){% elif skin == 'Violet' %}rgba(187,154,247,0.65){% elif skin == 'Aurora' %}rgba(150,165,240,0.65){% elif skin == 'Sunset' %}rgba(236,146,123,0.65){% elif skin == 'Lagoon' %}rgba(118,190,224,0.65){% elif skin == 'Citrus' %}rgba(199,205,105,0.65){% elif skin == 'Watermelon' %}rgba(201,165,142,0.65){% elif skin == 'Orchid' %}rgba(217,136,194,0.65){% elif skin == 'Reef' %}rgba(185,188,151,0.65){% elif skin == 'Frost' %}rgba(158,204,250,0.65){% elif skin == 'Horizon' %}rgba(122,162,247,0.65){% elif skin == 'Neon Pink' %}rgba(247,118,142,0.65){% elif skin == 'Neon Green' %}rgba(158,206,106,0.65){% elif skin == 'Etched' %}rgba(255,255,255,0.45){% elif skin == 'Obsidian' %}rgba(255,255,255,0.45){% elif skin == 'Nebula' %}rgba(124,112,226,0.65){% else %}rgba(0,188,212,0.65){% endif %}{% else %}rgba(255,255,255,0.07){% endif %} !important;
  box-shadow: {% if on %}{% if skin == 'Glass' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Poster' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Ember' %}0 0 16px rgba(224,175,104,0.25){% elif skin == 'Violet' %}0 0 16px rgba(187,154,247,0.25){% elif skin == 'Aurora' %}0 0 16px rgba(150,165,240,0.25){% elif skin == 'Sunset' %}0 0 16px rgba(236,146,123,0.25){% elif skin == 'Lagoon' %}0 0 16px rgba(118,190,224,0.25){% elif skin == 'Citrus' %}0 0 16px rgba(199,205,105,0.25){% elif skin == 'Watermelon' %}0 0 16px rgba(201,165,142,0.25){% elif skin == 'Orchid' %}0 0 16px rgba(217,136,194,0.25){% elif skin == 'Reef' %}0 0 16px rgba(185,188,151,0.25){% elif skin == 'Frost' %}0 0 16px rgba(158,204,250,0.25){% elif skin == 'Horizon' %}0 0 16px rgba(122,162,247,0.25){% elif skin == 'Neon Pink' %}0 0 16px rgba(247,118,142,0.25){% elif skin == 'Neon Green' %}0 0 16px rgba(158,206,106,0.25){% elif skin == 'Etched' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Obsidian' %}0 0 16px rgba(255,255,255,0.15){% elif skin == 'Nebula' %}0 0 16px rgba(124,112,226,0.25){% else %}0 0 16px rgba(0,188,212,0.25){% endif %}{% else %}none{% endif %} !important;
}
#name, div#name {
  color: {% if on %}#fff{% else %}rgba(255,255,255,0.45){% endif %} !important;
  text-shadow: {% if on %}{% if skin == 'Glass' %}0 0 8px rgba(255,255,255,0.50){% elif skin == 'Poster' %}0 0 8px rgba(255,255,255,0.50){% elif skin == 'Ember' %}0 0 8px rgba(224,175,104,0.8){% elif skin == 'Violet' %}0 0 8px rgba(187,154,247,0.8){% elif skin == 'Aurora' %}0 0 8px rgba(150,165,240,0.8){% elif skin == 'Sunset' %}0 0 8px rgba(236,146,123,0.8){% elif skin == 'Lagoon' %}0 0 8px rgba(118,190,224,0.8){% elif skin == 'Citrus' %}0 0 8px rgba(199,205,105,0.8){% elif skin == 'Watermelon' %}0 0 8px rgba(201,165,142,0.8){% elif skin == 'Orchid' %}0 0 8px rgba(217,136,194,0.8){% elif skin == 'Reef' %}0 0 8px rgba(185,188,151,0.8){% elif skin == 'Frost' %}0 0 8px rgba(158,204,250,0.8){% elif skin == 'Horizon' %}0 0 8px rgba(122,162,247,0.8){% elif skin == 'Neon Pink' %}0 0 8px rgba(247,118,142,0.8){% elif skin == 'Neon Green' %}0 0 8px rgba(158,206,106,0.8){% elif skin == 'Etched' %}0 0 8px rgba(255,255,255,0.50){% elif skin == 'Obsidian' %}0 0 8px rgba(255,255,255,0.50){% elif skin == 'Nebula' %}0 0 8px rgba(124,112,226,0.8){% else %}0 0 8px rgba(0,188,212,0.8){% endif %}{% else %}none{% endif %} !important;
}
/* /skin-period */

@media (min-width: 451px) { :host { padding: 0 !important; display: block !important; } ha-card { width: 100% !important; max-width: none !important; height: 68px !important; margin-bottom: 16px !important; } #name, div#name { white-space: normal !important; line-height: 1.6 !important; text-align: center !important; padding: 0 10px !important; } }

:host { display: flex !important; justify-content: center !important; padding: 12px 0 6px !important; margin: 0 !important; } ha-card { background: linear-gradient(135deg, #00bcd4 0%, #0097a7 100%) !important; border-radius: 14px !important; --ha-card-background: linear-gradient(135deg, #00bcd4 0%, #0097a7 100%) !important; box-shadow: 0 4px 20px rgba(0,188,212,0.4), inset 0 1px 0 rgba(255,255,255,0.2) !important; border: 1px solid rgba(255,255,255,0.15) !important; min-height: 0 !important; height: 52px !important; width: 255px !important; max-width: 255px !important; flex: 0 0 auto !important; display: flex !important; align-items: center !important; justify-content: center !important; padding: 0 !important; } #container { height: 100% !important; width: 100% !important; display: flex !important; align-items: center !important; justify-content: center !important; padding: 0 !important; } #name, div#name { overflow: visible !important; text-overflow: clip !important; max-width: none !important; width: auto !important; white-space: nowrap !important; padding: 0 !important; margin: 0 !important; line-height: 1 !important; display: flex !important; align-items: center !important; justify-content: center !important; }
/* epark-guard */
ha-card { background: linear-gradient(135deg, rgba(224,160,64,0.28), rgba(224,160,64,0.07)) !important; border: 1px solid rgba(224,160,64,0.65) !important; box-shadow: 0 0 16px rgba(224,160,64,0.25) !important; } #name, div#name { color: #fff !important; text-shadow: 0 0 8px rgba(224,160,64,0.8) !important; }

/* epark-guard */
{% set st = states('input_select.epark_stage') %}
ha-card { background: transparent !important; box-shadow: none !important; border: none !important; padding: 8px 20px 0 !important; margin: 0 !important; } ha-card > .card-content, .card-content { padding: 0 !important; } ha-markdown { display: block !important; padding: 0 !important; } :host { display: block; } ha-card { display: {{ 'block' if st in ['sending', 'sent', 'error'] else 'none' }} !important; }
